#requires -Version 5.1
# Run ONLY inside the Windows Sandbox generated by prepare-sandbox.ps1.
[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2
$inputDir = 'C:\PikoSandboxInput'
$outputDir = 'C:\PikoSandboxResults'
if ($env:USERNAME -ine 'WDAGUtilityAccount' -or $PSScriptRoot -ine $inputDir) {
    throw 'Safety guard: this script only runs as WDAGUtilityAccount from C:\PikoSandboxInput inside Windows Sandbox. Do not run it on the host.'
}
if (-not (Test-Path -LiteralPath $outputDir -PathType Container)) { throw 'Dedicated mapped results directory is missing.' }

$reportPath = Join-Path $outputDir 'report.json'
$logDir = Join-Path $outputDir 'commands'
New-Item -ItemType Directory -Path $logDir -Force | Out-Null
$work = Join-Path $env:LOCALAPPDATA ('PikoSandboxTest-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $work | Out-Null
$env:PIKO_HOME = Join-Path $work 'installation'
$steps = New-Object 'System.Collections.Generic.List[object]'
$report = [ordered]@{
    schemaVersion = 1
    status = 'running'
    startedAt = (Get-Date).ToUniversalTime().ToString('o')
    platform = [Environment]::OSVersion.VersionString
    architecture = $env:PROCESSOR_ARCHITECTURE
    root = $env:PIKO_HOME
    executableSha256 = $null
    scope = 'Clean Windows Sandbox; host input read-only; dedicated host results folder writable.'
    checks = @()
    error = $null
    limitations = @('Does not certify Windows 10 on a Windows 11 host.', 'No pi login/model/API-key tests.', 'No Ctrl+C or GUI interactive tests.', 'npm lifecycle scripts remain disabled.')
}
$server = $null
$transcript = $false
$exitCode = 1

. (Join-Path $PSScriptRoot 'sandbox-report.ps1')
function Assert-Check([bool]$Condition, [string]$Message) {
    if (-not $Condition) { throw $Message }
}
# ProcessStartInfo on Windows PowerShell 5.1 does not have ArgumentList.
# Quote according to the Windows argv rules, not by concatenating Shell code.
function Quote-Argument([AllowEmptyString()][string]$Value) {
    if ($Value.Length -gt 0 -and $Value -notmatch '[\s"]') { return $Value }
    $builder = New-Object Text.StringBuilder
    $null = $builder.Append('"')
    $slashes = 0
    foreach ($character in $Value.ToCharArray()) {
        if ($character -eq '\') { $slashes++; continue }
        if ($character -eq '"') {
            $null = $builder.Append(('\' * (2 * $slashes + 1))).Append('"')
        } else {
            $null = $builder.Append(('\' * $slashes)).Append($character)
        }
        $slashes = 0
    }
    $null = $builder.Append(('\' * (2 * $slashes))).Append('"')
    return $builder.ToString()
}
function Invoke-Check {
    param([string]$Name, [string]$File, [string[]]$Arguments = @(), [int]$ExpectedExit = 0, [int]$TimeoutSeconds = 300)
    Write-Host "[TEST] $Name"
    $info = New-Object Diagnostics.ProcessStartInfo
    $info.FileName = $File
    $info.Arguments = (($Arguments | ForEach-Object { Quote-Argument $_ }) -join ' ')
    $info.WorkingDirectory = $work
    $info.UseShellExecute = $false
    $info.RedirectStandardOutput = $true
    $info.RedirectStandardError = $true
    $info.CreateNoWindow = $true
    $process = New-Object Diagnostics.Process
    $process.StartInfo = $info
    $timer = [Diagnostics.Stopwatch]::StartNew()
    $result = [ordered]@{ name = $Name; file = $File; arguments = $Arguments; exitCode = $null; expectedExit = $ExpectedExit; passed = $false; durationMs = 0; stdout = ''; stderr = '' }
    try {
        if (-not $process.Start()) { throw "Unable to start $File" }
        $outTask = $process.StandardOutput.ReadToEndAsync()
        $errTask = $process.StandardError.ReadToEndAsync()
        if (-not $process.WaitForExit($TimeoutSeconds * 1000)) {
            # Kill descendants only inside this disposable Sandbox, then the parent.
            & "$env:WINDIR\System32\taskkill.exe" /PID $process.Id /T /F 2>&1 | Out-Null
            throw "Timed out after $TimeoutSeconds seconds: $Name"
        }
        $result.stdout = $outTask.GetAwaiter().GetResult()
        $result.stderr = $errTask.GetAwaiter().GetResult()
        $result.exitCode = $process.ExitCode
        $result.passed = $process.ExitCode -eq $ExpectedExit
    } catch {
        $result.stderr += "`n" + $_.Exception.Message
    } finally {
        $timer.Stop()
        $result.durationMs = $timer.ElapsedMilliseconds
        $process.Dispose()
        $number = $steps.Count + 1
        Write-SandboxText -Path (Join-Path $logDir "$number.stdout.txt") -Text $result.stdout
        Write-SandboxText -Path (Join-Path $logDir "$number.stderr.txt") -Text $result.stderr
        $steps.Add([pscustomobject]$result)
        Save-Report
    }
    if (-not $result.passed) { throw "Check failed: $Name (exit $($result.exitCode), expected $ExpectedExit). See commands/$number.stderr.txt" }
    return ($result.stdout + "`n" + $result.stderr).Trim()
}
function Read-State {
    return [IO.File]::ReadAllText((Join-Path $env:PIKO_HOME 'apps\piko\state.json')) | ConvertFrom-Json
}
function Find-Install([string]$Name) {
    $state = Read-State
    $found = @($state.installs.PSObject.Properties | ForEach-Object { $_.Value } | Where-Object { $_.name -eq $Name })
    Assert-Check ($found.Count -eq 1) "Expected exactly one installed $Name"
    return $found[0]
}

try {
    Start-Transcript -LiteralPath (Join-Path $outputDir 'transcript.txt') -Force | Out-Null
    $transcript = $true
    Save-Report
    Assert-Check ([Environment]::Is64BitOperatingSystem) 'Windows x64 Sandbox is required.'
    foreach ($command in @('node', 'npm', 'bun', 'piko')) {
        Assert-Check (-not (Get-Command $command -ErrorAction SilentlyContinue)) "Clean-image assumption failed: $command is already on PATH"
    }
    $config = Get-Content -LiteralPath (Join-Path $inputDir 'config.json') -Raw | ConvertFrom-Json
    Assert-Check ($config.schemaVersion -eq 1) 'Unsupported sandbox config.'
    $integrationOnly = $config.PSObject.Properties['integrationOnly'] -and $config.integrationOnly
    $report['integrationOnly'] = [bool]$integrationOnly
    $exe = Join-Path $inputDir 'piko.exe'
    $stream = [IO.File]::OpenRead($exe)
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $hash = ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-', '').ToLowerInvariant() }
    finally { $stream.Dispose(); $sha.Dispose() }
    $report.executableSha256 = $hash
    Assert-Check ($hash -eq $config.executableSha256) 'Mapped EXE hash differs from prepared configuration.'

    $version = Invoke-Check 'Self-contained startup without Node/Bun' $exe @('--version')
    $expectedVersion = if ($config.PSObject.Properties['pikoVersion']) { [string]$config.pikoVersion } else { '0.1.0' }
    Assert-Check ($version -eq $expectedVersion) 'Unexpected Piko version output.'
    $null = Invoke-Check 'Setup and Sandbox-only user PATH registration' $exe @('setup', '--path')
    $installedExe = Join-Path $env:PIKO_HOME 'apps\piko\piko.exe'
    Assert-Check (Test-Path -LiteralPath $installedExe) 'Piko installation is missing.'
    Assert-Check (-not (Test-Path -LiteralPath (Join-Path $env:PIKO_HOME 'state.json'))) 'State leaked into installation root.'
    Assert-Check (Test-Path -LiteralPath (Join-Path $env:PIKO_HOME 'apps\piko\state.json')) 'State must be beside piko.exe.'
    Assert-Check (-not (Test-Path -LiteralPath (Join-Path $env:PIKO_HOME 'apps\piko\current'))) 'Piko itself must not have current.'
    $shimDir = Join-Path $env:PIKO_HOME 'shims'
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    Assert-Check (@($userPath -split ';' | Where-Object { $_.TrimEnd('\') -ieq $shimDir.TrimEnd('\') }).Count -eq 1) 'User PATH must contain shims exactly once.'
    $null = Invoke-Check 'Idempotent setup PATH' $installedExe @('setup', '--path')
    $userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
    Assert-Check (@($userPath -split ';' | Where-Object { $_.TrimEnd('\') -ieq $shimDir.TrimEnd('\') }).Count -eq 1) 'Repeated setup duplicated PATH.'
    # The EXE cannot edit its parent process environment. Reload persisted settings explicitly.
    $env:Path = [Environment]::GetEnvironmentVariable('Path', 'Machine') + ';' + $userPath
    $shell = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $shellVersion = Invoke-Check 'New PowerShell discovers piko via configured PATH' $shell @('-NoProfile', '-NonInteractive', '-Command', 'piko --version')
    Assert-Check ($shellVersion -eq $expectedVersion) 'New PowerShell did not invoke the installed Piko version.'
    $batch = Join-Path $work 'path-check.cmd'
    '@echo off', 'piko --version', 'exit /b %errorlevel%' | Set-Content -LiteralPath $batch -Encoding ASCII
    $cmdVersion = Invoke-Check 'New CMD discovers piko via configured PATH' "$env:WINDIR\System32\cmd.exe" @('/d', '/c', 'path-check.cmd')
    Assert-Check ($cmdVersion -eq $expectedVersion) 'New CMD did not invoke the installed Piko version.'

    # No Bun/Node is needed to serve the read-only JSON fixtures in Sandbox.
    $sourceDir = Join-Path $inputDir 'source'
    $server = Start-Job -ArgumentList $sourceDir -ScriptBlock {
        param($Root, [int]$Port = 18765)
        $ErrorActionPreference = 'Stop'
        $listener = New-Object Net.HttpListener
        $listener.Prefixes.Add(('http://localhost:' + $Port + '/'))
        $listener.Start()
        try {
            while ($listener.IsListening) {
                $pendingRequest = $listener.GetContextAsync()
                # A blocking GetContext prevents Stop-Job from cancelling promptly.
                while (-not $pendingRequest.IsCompleted) { Start-Sleep -Milliseconds 50 }
                $context = $pendingRequest.GetAwaiter().GetResult()
                try {
                    $relative = [Uri]::UnescapeDataString($context.Request.Url.AbsolutePath).TrimStart('/')
                    $base = [IO.Path]::GetFullPath($Root).TrimEnd('\') + '\'
                    $file = [IO.Path]::GetFullPath((Join-Path $Root $relative))
                    $registryMetadata = Join-Path $Root 'registry\metadata.json'
                    $registryName = $relative -replace '^registry/', ''
                    $registry = if ($relative.StartsWith('registry/') -and [IO.File]::Exists($registryMetadata)) { [IO.File]::ReadAllText($registryMetadata) | ConvertFrom-Json } else { $null }
                    if ($registry -and $registry.PSObject.Properties[$registryName]) {
                        $bytes = [Text.Encoding]::UTF8.GetBytes(($registry.PSObject.Properties[$registryName].Value | ConvertTo-Json -Depth 20))
                        $context.Response.ContentType = 'application/json'
                        $context.Response.ContentLength64 = $bytes.Length
                        $context.Response.OutputStream.Write($bytes, 0, $bytes.Length)
                    } elseif (-not $file.StartsWith($base, [StringComparison]::OrdinalIgnoreCase) -or ([IO.Path]::GetExtension($file) -notin @('.json', '.tgz') -and $relative -notin @('integration-font.ttf', 'integration-command.exe', 'integration-bootstrap.ps1')) -or -not [IO.File]::Exists($file)) {
                        $context.Response.StatusCode = 404
                    } else {
                        $bytes = [IO.File]::ReadAllBytes($file)
                        $context.Response.ContentType = if ([IO.Path]::GetExtension($file) -eq '.json') { 'application/json' } else { 'application/octet-stream' }
                        $context.Response.ContentLength64 = $bytes.Length
                        $context.Response.OutputStream.Write($bytes, 0, $bytes.Length)
                    }
                } catch { $context.Response.StatusCode = 500 }
                finally { $context.Response.Close() }
            }
        } finally { $listener.Close() }
    }
    $ready = $false
    for ($attempt = 0; $attempt -lt 40; $attempt++) {
        try {
            $null = Invoke-WebRequest -Uri 'http://localhost:18765/index.json' -UseBasicParsing -TimeoutSec 2
            $ready = $true; break
        } catch {
            if ($server.State -eq 'Failed') { throw ('Fixture server failed: ' + ($server.ChildJobs[0].JobStateInfo.Reason | Out-String)) }
            Start-Sleep -Milliseconds 250
        }
    }
    Assert-Check $ready 'Local fixture server did not become ready.'
    $null = Invoke-Check 'Add example source' $installedExe @('source', 'add', 'main', 'http://localhost:18765/')
    if (-not $integrationOnly) {
    foreach ($spec in @('main/ripgrep@15.2.0', 'main/node@26.12.1')) {
        $null = Invoke-Check "Install $spec" $installedExe @('install', $spec)
        $name = if ($spec -like '*ripgrep*') { 'ripgrep' } else { 'node' }
        $installation = Find-Install $name
        Assert-Check ([bool]$installation.verified) "Downloaded $name must pass integrity verification."
        $current = Join-Path $env:PIKO_HOME ('apps\' + $installation.key + '\current')
        Assert-Check (-not (Test-Path -LiteralPath $current)) 'Install must not select current.'
        $null = Invoke-Check "Select $spec" $installedExe @('use', $spec)
        $item = Get-Item -LiteralPath $current -Force
        Assert-Check (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) 'current must be a junction, not a copy.'
    }
    Assert-Check ((Invoke-Check 'Managed Node version' (Join-Path $shimDir 'node.exe') @('--version')) -eq 'v26.12.1') 'Node version mismatch.'
    Assert-Check ((Invoke-Check 'ripgrep version' (Join-Path $shimDir 'rg.exe') @('--version')) -match '^ripgrep 15\.2\.0') 'ripgrep version mismatch.'
    $null = Invoke-Check 'Reject uninstalling default Node' $installedExe @('uninstall', 'main/node@26.12.1') -ExpectedExit 1
    $null = Invoke-Check 'Install npm CLI without lifecycle scripts' $installedExe @('install', 'npm:prettier@3.9.10')
    $null = Invoke-Check 'Select npm CLI series' $installedExe @('use', 'npm:prettier@3')
    Assert-Check ((Invoke-Check 'Prettier version' (Join-Path $shimDir 'prettier.exe') @('--version')) -eq '3.9.10') 'Prettier version mismatch.'
    $null = Invoke-Check 'Fixed Node update does not change version' $installedExe @('update', 'main/node')
    if ($config.PSObject.Properties['nextStage'] -and $config.nextStage) {
        $null = Invoke-Check 'Add executable alias for Prettier' $installedExe @('command', 'alias', 'format-code', 'npm:prettier', 'prettier')
        Assert-Check ((Invoke-Check 'Alias executes selected Prettier' (Join-Path $shimDir 'format-code.exe') @('--version')) -eq '3.9.10') 'Alias version mismatch.'
        $null = Invoke-Check 'Release default Prettier command without unselecting package' $installedExe @('command', 'release', 'prettier')
        Assert-Check (-not (Test-Path -LiteralPath (Join-Path $shimDir 'prettier.exe'))) 'Released command still exists.'
        Assert-Check ((Invoke-Check 'Alias survives release of original command' (Join-Path $shimDir 'format-code.exe') @('--version')) -eq '3.9.10') 'Alias was lost after command release.'
        $null = Invoke-Check 'Explicitly reclaim Prettier command' $installedExe @('command', 'claim', 'prettier', 'npm:prettier')
        $null = Invoke-Check 'Remove alias' $installedExe @('command', 'unalias', 'format-code')
        Assert-Check (-not (Test-Path -LiteralPath (Join-Path $shimDir 'format-code.exe'))) 'Removed alias still exists.'
        $null = Invoke-Check 'Install alternative provider with colliding rg command' $installedExe @('install', 'main/rg-alternative@1.0.0')
        $null = Invoke-Check 'Reject implicit command override' $installedExe @('use', 'main/rg-alternative@1.0.0') -ExpectedExit 1
        $null = Invoke-Check 'Select alternative current without claiming commands' $installedExe @('use', 'main/rg-alternative@1.0.0', '--no-commands')
        if ($config.PSObject.Properties['maintenanceStage'] -and $config.maintenanceStage) {
            Assert-Check ((Invoke-Check 'Selected manifest env reaches managed child only' (Join-Path $shimDir 'node.exe') @('-p','process.env.TOOL_FIXTURE_VERSION')) -eq '1.0.0') 'Manifest env was not applied.'
            Assert-Check (-not (Test-Path Env:TOOL_FIXTURE_VERSION)) 'Manifest env changed parent process.'
        }
        $null = Invoke-Check 'Explicitly transfer rg ownership' $installedExe @('command', 'claim', 'rg', 'main/rg-alternative')
        $null = Invoke-Check 'Restore rg ownership without removing alternative current' $installedExe @('command', 'claim', 'rg', 'main/ripgrep')
        $null = Invoke-Check 'Unselect alternative provider' $installedExe @('unuse', 'main/rg-alternative')
        $null = Invoke-Check 'Uninstall alternative provider' $installedExe @('uninstall', 'main/rg-alternative@1.0.0')

        $null = Invoke-Check 'Install persistent-data fixture' $installedExe @('install', 'main/saved-fixture@1.0.0')
        $saved = Find-Install 'saved-fixture'
        $data = Join-Path $env:PIKO_HOME ('persist\' + $saved.key + '\settings')
        [IO.File]::WriteAllText((Join-Path $data 'keep.txt'), 'sandbox-user-data')
        $null = Invoke-Check 'Reject cleanup while any installed version refers to data' $installedExe @('cleanup', 'main/saved-fixture', '--data', '--yes') -ExpectedExit 1
        $null = Invoke-Check 'Uninstall fixture but retain data' $installedExe @('uninstall', 'main/saved-fixture@1.0.0')
        Assert-Check ([IO.File]::ReadAllText((Join-Path $data 'keep.txt')) -eq 'sandbox-user-data') 'Ordinary uninstall lost persistent data.'
        $untracked = Join-Path $env:PIKO_HOME ('persist\' + $saved.key + '\outside-declared-path.txt')
        [IO.File]::WriteAllText($untracked, 'must-not-delete')
        $null = Invoke-Check 'Preview exact data cleanup paths' $installedExe @('cleanup', 'main/saved-fixture', '--data', '--dry-run')
        $null = Invoke-Check 'Reject unconfirmed noninteractive data cleanup' $installedExe @('cleanup', 'main/saved-fixture', '--data') -ExpectedExit 1
        $null = Invoke-Check 'Explicitly delete only recorded persistent directories' $installedExe @('cleanup', 'main/saved-fixture', '--data', '--yes')
        Assert-Check (-not (Test-Path -LiteralPath $data)) 'Confirmed persistent directory was not removed.'
        Assert-Check ([IO.File]::ReadAllText($untracked) -eq 'must-not-delete') 'Cleanup touched an untracked file.'
    }
    $null = Invoke-Check 'Unselect ripgrep' $installedExe @('unuse', 'main/ripgrep')
    Assert-Check (-not (Test-Path -LiteralPath (Join-Path $shimDir 'rg.exe'))) 'unuse did not remove rg shim.'
    $null = Invoke-Check 'Reselect installed ripgrep' $installedExe @('use', 'main/ripgrep@15.2.0')
    $null = Invoke-Check 'Force uninstall default ripgrep' $installedExe @('uninstall', 'main/ripgrep@15.2.0', '--force')
    Assert-Check (-not (Test-Path -LiteralPath (Join-Path $shimDir 'rg.exe'))) 'Uninstall left an active rg shim.'
    if ($config.includePi) {
        $spec = 'npm:@mariozechner/pi-coding-agent@0.73.1'
        $null = Invoke-Check 'Install pi without lifecycle scripts' $installedExe @('install', $spec) -TimeoutSeconds 600
        $null = Invoke-Check 'Select pi' $installedExe @('use', $spec)
        Assert-Check ((Invoke-Check 'pi version (stdout or stderr)' (Join-Path $shimDir 'pi.exe') @('--version')) -match '0\.73\.1') 'pi did not report its version.'
        $null = Invoke-Check 'List skipped pi lifecycle scripts' $installedExe @('scripts', 'list', $spec)
    }
    if ($config.PSObject.Properties['scriptStage'] -and $config.scriptStage) {
        $report.limitations = @('Does not certify Windows 10.', 'No pi login/model tests.', 'Approved scripts are not sandboxed by Piko; external effects cannot be undone.')
        $spec = 'npm:@piko-fixture/scripts@1.0.0'
        $oldRegistry = $env:PIKO_NPM_REGISTRY
        try {
            $env:PIKO_NPM_REGISTRY = 'http://localhost:18765/registry/'
            $null = Invoke-Check 'Install harmless lifecycle fixture without executing scripts' $installedExe @('install', $spec)
            $fixture = Find-Install '@piko-fixture/scripts'
            $packageDir = Join-Path $env:PIKO_HOME $fixture.dir
            $top = Join-Path $packageDir 'node_modules\@piko-fixture\scripts'
            $dependency = Join-Path $packageDir 'node_modules\piko-fixture-helper'
            Assert-Check (-not (Test-Path (Join-Path $top 'generated.txt'))) 'Installation ran a lifecycle script.'
            $null = Invoke-Check 'Inspect checked script content and integrity bindings' $installedExe @('scripts', 'list', $spec)
            $null = Invoke-Check 'Reject rebuild without approvals' $installedExe @('scripts', 'rebuild', $spec) -ExpectedExit 1
            $null = Invoke-Check 'Reject unconfirmed noninteractive script approval' $installedExe @('scripts', 'approve', $spec) -ExpectedExit 1
            $null = Invoke-Check 'Approve only exact top-level fixture contents' $installedExe @('scripts', 'approve', $spec, '--yes')
            Assert-Check (-not (Test-Path (Join-Path $top 'generated.txt'))) 'Approval itself executed scripts.'
            $null = Invoke-Check 'Select fixture before staged rebuild' $installedExe @('use', $spec)
            $null = Invoke-Check 'Rebuild approved top-level package with dependencies denied' $installedExe @('scripts', 'rebuild', $spec)
            Assert-Check (Test-Path (Join-Path $top 'generated.txt')) 'Approved fixture did not run.'
            Assert-Check (-not (Test-Path (Join-Path $dependency 'dependency-generated.txt'))) 'Approving top-level implicitly ran dependency scripts.'
            Assert-Check ((Invoke-Check 'Rebuilt fixture shim still works' (Join-Path $shimDir 'piko-script-fixture.exe') @('--version')) -eq '1.0.0') 'Rebuilt fixture CLI failed.'
            $env:PIKO_FIXTURE_FAIL = '1'
            try { $null = Invoke-Check 'Failed staged script preserves original working installation' $installedExe @('scripts', 'rebuild', $spec) -ExpectedExit 1 }
            finally { Remove-Item Env:PIKO_FIXTURE_FAIL -ErrorAction SilentlyContinue }
            Assert-Check ((Invoke-Check 'Fixture survives failed rebuild' (Join-Path $shimDir 'piko-script-fixture.exe') @('--version')) -eq '1.0.0') 'Failed rebuild replaced working CLI.'
            $null = Invoke-Check 'Revoke top-level approval' $installedExe @('scripts', 'revoke', $spec)
            $null = Invoke-Check 'Revoked approval cannot rebuild' $installedExe @('scripts', 'rebuild', $spec) -ExpectedExit 1
            $null = Invoke-Check 'Separately approve exact dependency contents' $installedExe @('scripts', 'approve', $spec, '--package-path', 'node_modules/piko-fixture-helper', '--yes')
            $null = Invoke-Check 'Rebuild dependency only from original checked snapshot' $installedExe @('scripts', 'rebuild', $spec)
            Assert-Check (-not (Test-Path (Join-Path $top 'generated.txt'))) 'Revoked top-level script ran again.'
            Assert-Check (Test-Path (Join-Path $dependency 'dependency-generated.txt')) 'Explicit dependency approval did not execute.'
            $cli = Join-Path $top 'cli.cjs'
            $original = [IO.File]::ReadAllBytes($cli)
            [IO.File]::AppendAllText($cli, "`n// modified")
            try { $null = Invoke-Check 'Reject changed installed content before execution' $installedExe @('scripts', 'rebuild', $spec) -ExpectedExit 1 }
            finally { [IO.File]::WriteAllBytes($cli, $original) }
            $null = Invoke-Check 'Install new version without carrying approvals' $installedExe @('install', 'npm:@piko-fixture/scripts@1.1.0')
            $null = Invoke-Check 'New version requires fresh approval' $installedExe @('scripts', 'rebuild', 'npm:@piko-fixture/scripts@1.1.0') -ExpectedExit 1
            # Batch previews use the restored public registry after this stage.
            # Retain fixture versions and snapshots, but release its default.
            $null = Invoke-Check 'Unselect local-registry fixture after script tests' $installedExe @('unuse', 'npm:@piko-fixture/scripts')
            Assert-Check (-not (Read-State).defaults.PSObject.Properties[$fixture.key]) 'Local-registry fixture is still selected.'
        } finally {
            if ($null -eq $oldRegistry) { Remove-Item Env:PIKO_NPM_REGISTRY -ErrorAction SilentlyContinue } else { $env:PIKO_NPM_REGISTRY = $oldRegistry }
        }
    }
    }
    if ($config.PSObject.Properties['integrationStage'] -and $config.integrationStage) {
        . (Join-Path $inputDir 'integrations.ps1')
    }
    if (-not $integrationOnly -and $config.PSObject.Properties['maintenanceStage'] -and $config.maintenanceStage) {
        $null = Invoke-Check 'Package information includes refreshed source versions' $installedExe @('info', 'main/node')
        $null = Invoke-Check 'Preview batch updates without mutations' $installedExe @('update', '--all', '--dry-run')
        $null = Invoke-Check 'List checksummed artifact and protected npm snapshot caches' $installedExe @('cache', 'list')
        $null = Invoke-Check 'Preview unreferenced cache cleanup' $installedExe @('cache', 'clean', '--dry-run')
        $null = Invoke-Check 'Reject cache deletion without confirmation' $installedExe @('cache', 'clean') -ExpectedExit 1
        $null = Invoke-Check 'Clean only unreferenced snapshots and download caches' $installedExe @('cache', 'clean', '--yes')
        Assert-Check ((Invoke-Check 'Prettier remains executable after cache cleanup' (Join-Path $shimDir 'prettier.exe') @('--version')) -eq '3.9.10') 'Cache cleanup damaged installed software.'
        $probe = Join-Path $work 'signal-probe.cjs'
        [IO.File]::WriteAllText($probe, "const fs=require('fs'),p=process.argv[2];process.on('SIGINT',()=>{fs.writeFileSync(p,'interrupted');process.exit(130)});fs.writeFileSync(p+'.ready','ready');setInterval(()=>{},1000);")
        $marker = Join-Path $work 'ctrl-c.marker'
        $null = Invoke-Check 'Isolated console Ctrl+C reaches managed Node and shim exits' $shell @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',(Join-Path $inputDir 'ctrl-c.test.ps1'),'-Executable',(Join-Path $shimDir 'node.exe'),'-Probe',$probe,'-Marker',$marker)
        Assert-Check ([IO.File]::ReadAllText($marker) -eq 'interrupted') 'Ctrl+C marker missing.'
        $stateBeforeUpgrade = [IO.File]::ReadAllText((Join-Path $env:PIKO_HOME 'apps\piko\state.json'))
        $null = Invoke-Check 'List orphan installations without adopting unknown directories' $installedExe @('maintenance','orphans')
        $null = Invoke-Check 'Reject orphan quarantine without confirmation' $installedExe @('maintenance','quarantine') -ExpectedExit 1
        $null = Invoke-Check 'Self update requires explicit trusted checksum' $installedExe @('self','update',$exe,'--sha256',('0' * 64),'--yes') -ExpectedExit 1
        $pending = Invoke-Check 'Prepare self update after current process exits' $installedExe @('self','update',$exe,'--sha256',$config.executableSha256,'--yes')
        $upgradeJournal = Join-Path $env:PIKO_HOME 'operations\self-update.json'
        for ($n=0; $n -lt 300 -and (Test-Path -LiteralPath $upgradeJournal); $n++) { Start-Sleep -Milliseconds 100 }
        Assert-Check (-not (Test-Path -LiteralPath $upgradeJournal)) 'Self-update remained pending; inspect apps/piko/update.log.'
        $upgrade = Invoke-Check 'Self update final status' $installedExe @('self','status')
        Assert-Check ((($upgrade | ConvertFrom-Json).last.phase) -eq 'committed') 'Self update did not commit.'
        $null = Invoke-Check 'Rebound Piko shim reports expected version' (Join-Path $shimDir 'piko.exe') @('--version')
        Assert-Check ((Invoke-Check 'Managed Node survives Piko replacement' (Join-Path $shimDir 'node.exe') @('--version')) -eq 'v26.12.1') 'Node shim did not survive replacement.'
        Assert-Check ((Read-State).schemaVersion -ge 3) 'Upgrade lost state schema.'
        Assert-Check ([IO.File]::ReadAllText((Join-Path $env:PIKO_HOME 'apps\piko\state.json')) -eq $stateBeforeUpgrade) 'Upgrade modified state.json.'
    }
    $null = Invoke-Check 'Final doctor' $installedExe @('doctor')
    $null = Invoke-Check 'Final package inventory' $installedExe @('list')
    $report.status = 'passed'
    $exitCode = 0
    Write-Host 'PASS: Sandbox checks completed. Results are available in the dedicated host results folder.' -ForegroundColor Green
} catch {
    $report.status = 'failed'
    $report.error = ($_ | Out-String)
    Write-Host ('FAIL: ' + $_.Exception.Message) -ForegroundColor Red
} finally {
    if ($server) { Stop-Job -Job $server -ErrorAction SilentlyContinue; Remove-Job -Job $server -Force -ErrorAction SilentlyContinue }
    $report.finishedAt = (Get-Date).ToUniversalTime().ToString('o')
    $report.exitCode = $exitCode
    try { Save-Report }
    finally {
        if ($transcript) { Stop-Transcript | Out-Null }
        Write-Host "Report: $reportPath"
        Write-Host "Sandbox installation retained for inspection: $env:PIKO_HOME"
        Write-Host 'Close Windows Sandbox manually when finished. Logs persist on the host; Sandbox-installed software does not.'
    }
}
# -NoExit keeps the Sandbox console open for inspection; report.json is the authoritative verdict.
$global:LASTEXITCODE = $exitCode
